import {GALAXY_SYSTEMS,galaxyFlight} from './galaxy.js';
import {RES,LABEL,ICON,BUILDINGS,TECHS,SHIPS,TARGETS,vector,isFreighter,planetImagePath} from './config.js';
import {newGame,getPlanet,stats,buildInfo,researchInfo,need,shipInfo,cargoCapacity,flightInfo,legInfo,routeInfo,advance,act,fleetManifest,fleetCapacity,checkedFleet} from './engine.js';
import {SAVE_KEY,loadGame,saveGame,parseSave} from './storage.js';
import {CLOUD_CONFIG} from './cloud-config.js';
import {connectCloud,CloudConflict} from './cloud.js';
import {pvpView,pvpSettings,pvpEstimate} from './pvp-ui.js';

const fleetDrafts=new Map();
const pvpDraft={};
function gameNow(){return cloud?.authoritative?cloud.now:Date.now();}
function adoptServer(result){const active=state?.active;state=result.state;if(state&&state.planets.some(p=>p.id===active))state.active=active;cloudDirty=false;cloudMessage='● Server abgeglichen';cloudLastSave=Date.now();if(state)saveGame(state,localStorage,saveKey());}
async function serverAction(request){if(readOnly||cloudBlocked||galaxyBusy||cloudSaving||!cloud?.authoritative)return;galaxyBusy=true;try{adoptServer(await cloud.gameRequest(request));if(request.type==='attack')toast('Angriffsflotte gestartet.');}catch(e){toast(e.message);if(cloud.pending)settings();}finally{galaxyBusy=false;render();}}
let routeEditId=0,routeSection='existing',routeQuery='',routeFilter='all';
let fleetSection='hangar',shipCategory='freighter';
let galaxySection='tutorial',galaxySystem='helion',galaxyTarget='',galaxyData=null,galaxyError='',galaxyBusy=false,galaxyRequest=0,galaxyLast=0,mapCleanup=null,galaxyCamera=null;
const fleetSections={pvp:['✧','PvP & Verteidigung','Angriffe, Warnungen und Kampfberichte'],hangar:['⌁','Hangar & Werft','Schiffe bauen und im Orbit'],orders:['➤','Flottenaufträge','Liefern, abholen, stationieren'],routes:['⇄','Handelsrouten','Stopps planen und verwalten'],overview:['◎','Gesamtübersicht','Alle Flotten und Berichte']};
const app=document.getElementById('app');let state=null,tab='overview',readOnly=false,storageOK=true,lastSave=0;
let cloud=null,cloudBlocked=CLOUD_CONFIG.enabled,cloudSaving=false,cloudAuthBusy=false,cloudDirty=false,cloudGeneration=0,cloudLastSave=0,cloudMessage='● Lokal gespeichert',cloudLastAttempt=0,activeAccountId=null;
const tabs={overview:['◉','Übersicht'],build:['⚒','Bauen'],research:['⚗','Forschung'],galaxy:['◎','Galaxie'],fleet:['➤','Flotten'],leaderboard:['♛','Rangliste']};
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.floor(n).toLocaleString('de-DE');
const duration=ms=>{const t=Math.max(0,Math.ceil(ms/1000));return t>=3600?`${Math.floor(t/3600)} Std ${Math.floor(t%3600/60)} Min`:t>=60?`${Math.floor(t/60)} Min ${t%60} Sek`:`${t} Sek`;};
const costHTML=c=>RES.filter(k=>c[k]).map(k=>`<span>${ICON[k]} ${fmt(c[k])} ${LABEL[k]}</span>`).join('');
const button=(label,action,attrs='',disabled='')=>`<button data-action="${action}" ${attrs} ${disabled?'disabled':''}>${label}</button>`;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500);}
function persist(force=false){if(readOnly||cloudBlocked)return;try{if(state&&(force||Date.now()-lastSave>3000)){saveGame(state,localStorage,saveKey());lastSave=Date.now();storageOK=true;if(cloud?.user&&!cloud.authoritative){cloudDirty=true;cloudGeneration++;localStorage.setItem(saveKey()+'-cloud-meta',JSON.stringify({revision:cloud.revision,pending:true}));if(force){clearTimeout(persist.cloudTimer);persist.cloudTimer=setTimeout(()=>void flushCloud(),2000);}}}}catch{storageOK=false;toast('Speichern nicht möglich. Bitte Spielstand exportieren.');}}
function orb(p,size=''){const imagePath=planetImagePath(p);const level=Object.values(p.buildings||{}).reduce((a,b)=>a+b,0);return `<div class="planet-art asset-planet ${size}" aria-label="${esc(p.kind)} aus dem All"><img src="${imagePath}" alt="${esc(p.name||'Heimatplanet')}" width="768" height="768" decoding="async"><div class="lights" style="opacity:${Math.min(.85,level/40)}"></div></div>`;}
function progress(job,label){const progress=Math.min(100,Math.max(0,100*(state.time-job.start)/(job.end-job.start)));return `<div class="job"><div class="split"><strong>${esc(label)}</strong><span class="muted" data-due="${job.end}">${duration(job.end-state.time)}</span></div><div class="track"><i style="width:${progress}%"></i></div></div>`;}
function affordable(p,c){return RES.every(k=>p.resources[k]>=c[k]);}
function nextGoal(){const p=getPlanet(state,'home');if(!p.buildings.lab)return ['Forschung beginnen','Baue Forschungslabor Stufe 1.','build'];if(!state.tech.scout)return ['Den Horizont erweitern','Erforsche Sensortechnik Stufe 1.','research'];if(!p.buildings.shipyard)return ['Bereit zum Aufbruch','Baue Schiffswerft Stufe 1.','build'];if(!state.discovered.length)return ['Deine erste Entdeckung','Baue eine Sonde unter Flotten und erkunde einen Planeten.','galaxy'];if(!state.tech.colonization)return ['Eine neue Welt','Baue Labor Stufe 2 und erforsche Kolonisierung.','research'];if(state.planets.length===1)return ['Die erste Kolonie','Baue ein Kolonieschiff und besiedle dein erkundetes Ziel.','galaxy'];if(!state.tech.logistics)return ['Welten verbinden','Erforsche Transporttechnik und baue einen Frachter.','research'];if(!state.reports.some(r=>r.title==='Transport angekommen'))return ['Dein Imperium verbinden','Baue Kolonieminen aus und transportiere Material nach Aurelia.','fleet'];return ['Der Kreislauf steht','Erkunde die nächste Welt und entwickle deine Spezialisierung weiter.','galaxy'];}
function overview(p){const z=stats(state,p),goal=nextGoal();return `<section class="hero"><div class="hero-copy"><span class="eyebrow">${esc(p.kind)} · [${esc(p.coord)}]</span><h1>${esc(p.name)}</h1><p>${p.id==='home'?'Hier beginnt dein Imperium.':'Deine Wirtschaft hat eine neue Heimat.'}</p><div class="chips"><span>${state.planets.length-1} Kolonie${state.planets.length===2?'':'n'}</span><span>${Object.values(p.buildings).reduce((a,b)=>a+b,0)} Ausbaustufen</span></div></div>${orb(p)}</section><div class="two-columns"><section class="panel accent"><span class="eyebrow">DEIN NÄCHSTES ZIEL</span><h2>${goal[0]}</h2><p>${goal[1]}</p>${button('Zum nächsten Schritt →','tab',`data-tab="${goal[2]}"`)}</section><section class="panel"><h2>Lokale Produktion</h2>${RES.map(k=>`<div class="stat-row"><span>${ICON[k]} ${LABEL[k]}</span><strong>${fmt(z.rates[k])} / Std</strong></div>`).join('')}<div class="stat-row"><span>Energieversorgung</span><strong class="${z.ratio<1?'amber':'cyan'}">${Math.round(z.ratio*100)} %</strong></div><p class="fine">${z.ratio<1?'Baue Energie aus: Unterversorgung bremst alle Minen.':'Die Minen arbeiten mit voller Leistung.'}</p></section></div><section class="panel"><h2>Aktuelle Aufträge</h2>${p.build?progress(p.build,`${BUILDINGS[p.build.key].name} · Stufe ${p.build.level}`):'<p class="muted">Bauplatz frei. Wähle den nächsten Ausbau.</p>'}${state.research?progress(state.research,`${TECHS[state.research.key].name} · Stufe ${state.research.level}`):''}${p.shipjob?progress(p.shipjob,`${p.shipjob.count} × ${SHIPS[p.shipjob.key].name}`):''}</section><section><div class="section-title"><h2>Deine Welten</h2><span class="muted">Materialien sind lokal</span></div><div class="world-grid">${state.planets.map(q=>`<button class="world-card ${q.id===p.id?'selected':''}" data-action="planet" data-id="${q.id}">${orb(q,'small')}<strong>${esc(q.name)}</strong><span class="muted">${esc(q.kind)}</span></button>`).join('')}</div></section>`;}
function buildingEnergy(p,key){const next=structuredClone(p);next.buildings[key]++;const now=stats(state,p),after=stats(state,next),extra=after.demand-now.demand,gain=after.supply-now.supply,balance=after.supply-after.demand,n=v=>v.toLocaleString('de-DE',{maximumFractionDigits:2});return `<p class="fine ${balance<0?'amber':'cyan'}">ϟ ${extra>0?`Nächste Stufe benötigt +${n(extra)} Energie`:gain>0?`Nächste Stufe liefert +${n(gain)} Energie`:'Kein zusätzlicher Energiebedarf'} · ${balance<0?`Danach fehlen ${n(-balance)} Energie`:`Danach ${n(balance)} Energie frei`}</p>`;}
function buildings(p){return `<div class="page-heading"><span class="eyebrow">${esc(p.name)}</span><h1>Bauen</h1><p>Ein Bauauftrag pro Planet. Forschungen laufen parallel.</p></div>${p.build?progress(p.build,`${BUILDINGS[p.build.key].name} → Stufe ${p.build.level}`):''}<div class="list">${Object.entries(BUILDINGS).map(([key,b])=>{const inf=buildInfo(state,p,key),reason=inf.reason||(p.build?'Bauplatz belegt.':'')||(!affordable(p,inf.cost)?'Lokale Ressourcen fehlen.':'');const l=p.buildings[key];let effect=b.description;if(RES.includes(key)){const next=structuredClone(p);next.buildings[key]++;effect=`Förderung jetzt ${fmt(stats(state,p).rates[key])}/Std · nächste Stufe ${fmt(stats(state,next).rates[key])}/Std (aktuelle Energieversorgung).`;}return `<article class="panel build-row ${inf.reason?'locked':''}"><div class="item-icon asset-item"><img src="${b.asset||'./assets/buildings-research-v1/buildings/'+key+'.webp'}" alt="" width="96" height="96" loading="lazy" decoding="async"></div><div class="item-copy"><h2>${b.name} <span class="muted">· Stufe ${l}</span></h2><p>${effect}</p>${buildingEnergy(p,key)}<div class="cost">${costHTML(inf.cost)}<span>◷ ${duration(inf.ms)}</span></div>${reason?`<div class="requirement">${esc(reason)}</div>`:''}</div>${button(`Stufe ${l+1} bauen`,'build',`data-key="${key}"`,reason||readOnly)}</article>`;}).join('')}</div>`;}
function research(p){return `<div class="page-heading"><span class="eyebrow">IMPERIUMSWEIT · LABOR ${p.buildings.lab} AUF ${esc(p.name)}</span><h1>Forschung</h1><p>Neue Möglichkeiten für alle deine Welten. Kosten werden hier bezahlt.</p></div><section class="panel"><h2>Vom Tutorial in die Galaxie</h2><p>Kolonisierung 1–3: drei Kolonien neben der Heimatwelt. Danach folgen Verbrennung → Staustrahl → Impuls → Hyperraum. Stufe 3 des vorherigen Antriebs öffnet die nächste Triebwerksforschung.</p><p class="fine">Neue Triebwerke: Stufe 1 schaltet die passende Kriegsschiffklasse frei, Stufe 2 den passenden Frachter. Jede Stufe verbessert nur Schiffe dieses Triebwerks. Kolonisierung 4/5/6 erfordert Staustrahl/Impuls/Hyperraum 1; diese zusätzlichen Plätze sind für die gemeinsame Galaxie. Fernsonde: Sensortechnik 2 + Staustrahl 1. Interstellares Kolonieschiff: Kolonisierung 4 + Staustrahl 1.</p></section>${state.research?progress(state.research,`${TECHS[state.research.key].name} → Stufe ${state.research.level}`):''}<div class="list">${Object.entries(TECHS).map(([key,t])=>{const inf=researchInfo(state,p,key),reason=inf.reason||(state.research?'Forschungslabor beschäftigt.':'')||(!affordable(p,inf.cost)?'Lokale Ressourcen fehlen.':'');return `<article class="panel build-row ${inf.reason?'locked':''}"><div class="item-icon asset-item"><img src="${t.asset||'./assets/buildings-research-v1/research/'+key+'.webp'}" alt="" width="96" height="96" loading="lazy" decoding="async"></div><div class="item-copy"><h2>${t.name} <span class="muted">· Stufe ${state.tech[key]} / ${t.max}</span></h2><p>${t.description}</p><div class="cost">${costHTML(inf.cost)}<span>◷ ${duration(inf.ms)}</span></div>${reason?`<div class="requirement">${esc(reason)}</div>`:''}</div>${button('Erforschen','research',`data-key="${key}"`,reason||readOnly)}</article>`;}).join('')}</div>`;}
function tutorialGalaxy(p){return `<div class="page-heading"><span class="eyebrow">AUFBRUCH VON ${esc(p.name)}</span><h1>${esc(state.systemName||'Mein Sonnensystem')}</h1><form id="system-name-form"><label>Name deines Sonnensystems<input name="systemName" maxlength="30" required value="${esc(state.systemName||'')}" placeholder="z. B. Solara"></label><button ${readOnly||cloudBlocked||galaxyBusy?'disabled':''}>Namen speichern</button></form><p class="fine">Systemname und Commander-Name sind für angemeldete Spieler auf der Galaxiekarte sichtbar.</p><p>Erkunde und besiedle Ferrum, Nereus und Thalassa. Kolonisierung 1–3 erlaubt alle drei Kolonien neben deiner Heimatwelt.</p></div><div class="system-map"><span class="sun"></span>${TARGETS.map((t,i)=>`<span class="map-planet" style="--planet:${t.color};left:${28+i*25}%;top:${40+(i%2)*14}%">${state.discovered.includes(t.id)?t.name:'?'}</span>`).join('')}</div><div class="world-grid targets">${TARGETS.map(t=>{const known=state.discovered.includes(t.id),owned=state.planets.some(p=>p.id===t.id),mission=state.missions.find(m=>m.to===t.id&&m.type==='colony'),canColony=known&&!owned&&!mission&&state.planets.length-1+state.missions.filter(m=>m.type==='colony').length<state.tech.colonization&&p.ships.colony;const f=flightInfo(state,p,t,1,true);return `<article class="panel target"><div class="target-visual">${orb({...t,buildings:{}},'medium')}</div><span class="eyebrow">[${t.coord}]</span><h2>${known?t.name:'Unbekannte Welt'}</h2><p>${known?t.kind:'Ein Signal am Rand deines Systems.'}</p>${known?`<div class="yields">${RES.map((k,i)=>`<div><span>${LABEL[k]}</span><strong>×${t.mult[i].toLocaleString('de-DE')}</strong><div class="track"><i style="width:${Math.min(100,t.mult[i]/2*100)}%"></i></div></div>`).join('')}</div><p class="fine">Energiebedarf ×${t.energy} · ${t.ocean?'Gezeitenkraftwerke möglich':'Keine Gezeitenkraftwerke'}</p>`:'<div class="unknown">Vorkommen noch nicht bekannt</div>'}<p class="fine">Sonde: ${duration(f.ms)} je Strecke · ${f.fuel} Treibstoff insgesamt</p>${button('Sonde senden','probe',`data-to="${t.id}"`,!p.ships.probe||readOnly||p.system)}${known?button(owned?'Besiedelt':mission?'Kolonieschiff unterwegs':'Kolonisieren','colony',`data-to="${t.id}"`,!canColony||readOnly||p.system):''}${known&&!owned&&!mission?'<p class="fine">Benötigt freien Kolonieplatz + Kolonieschiff. Zusätzlich mitnehmen: 350 Metall, 250 Kristall, 100 Treibstoff.</p>':''}</article>`;}).join('')}</div><section class="panel"><h2>Vorbereitung</h2><p>Verfügbare Sonden: <strong>${p.ships.probe}</strong> · Kolonieschiffe: <strong>${p.ships.colony}</strong> · Tutorial-Kolonieplätze: <strong>${state.planets.length-1} / ${Math.min(3,state.tech.colonization)}</strong> · Spätere Galaxieplätze: <strong>${Math.max(0,state.tech.colonization-3)}</strong></p>${button('Zur Schiffswerft →','tab','data-tab="fleet"')}</section>`;}
let galaxyExpanded=false;
function clearGalaxy(){galaxyExpanded=false;galaxyRequest++;galaxyData=null;galaxyError='';galaxyBusy=false;galaxyLast=0;galaxyTarget='';galaxyCamera=null;}
function galaxyMissionsHTML(){return galaxyData?.missions.length?`<h3>Galaxieflüge · ${galaxyData.missions.length}</h3>${galaxyData.missions.map(m=>`<article class="mission"><strong>${m.kind==='scan'?'Fernsonde':'Interstellares Kolonieschiff'} → ${esc(m.system)} · P${m.slot}</strong><p>${m.kind==='scan'&&m.arrival<=Date.now()?'Untersucht · Sonde auf dem Rückweg':'Unterwegs'}</p><span data-due="${m.due}">${duration(m.due-Date.now())}</span></article>`).join('')}`:'';}
function galaxyOwnerLabel(p){return p.owner==='mine'?`${p.reserved?'Dein Kolonieschiff unterwegs':'Deine Kolonie'} · ${esc(p.commander||state.name)}`:p.owner==='foreign'?`${p.reserved?'Reserviert':'Besiedelt'} durch ${esc(p.commander||'Commander')}`:p.owner==='free'?'Unbesiedelt':'Besitzstatus noch nicht verfügbar';}
function galaxy(p){
 const menu=`<div class="galaxy-menu" aria-label="Kartenbereiche">${button('Mein Sonnensystem','galaxy-section',`data-section="tutorial" aria-pressed="${galaxySection==='tutorial'}"`)}${button('Gemeinsame Galaxie','galaxy-section',`data-section="shared" aria-pressed="${galaxySection==='shared'}"`)}</div>`;
 if(galaxySection==='tutorial')return menu+tutorialGalaxy(p);
 const systems=galaxyData?.systems||GALAXY_SYSTEMS,selected=systems.find(s=>s.id===galaxySystem)||systems[0],start=galaxyData?.start;
 const planets=(galaxyData?.planets||[]).filter(q=>q.system===selected.id),target=planets.find(q=>q.id===galaxyTarget)||planets[0];
 const remote=target?{...selected,slot:target.slot}:selected,f=start?galaxyFlight(state,p,remote,start):null;
 const disabled=readOnly||cloudBlocked||galaxyBusy||!galaxyData;
 const flight=f?`<div class="trip-card"><h3>Flug ab ${esc(p.name)}</h3><div class="stat-row"><span>Fernsonde · je Strecke</span><strong>${duration(f.ms)}</strong></div><div class="stat-row"><span>Treibstoff · Hin & zurück</span><strong>${f.fuel}</strong></div><div class="stat-row"><span>Entfernung</span><strong>${f.distance.toFixed(1)} AE</strong></div></div>`:'<p class="fine">Persönliche Entfernung und Flugwerte werden nach der Anmeldung geladen.</p>';
 const scanPending=target&&galaxyData?.missions.some(m=>m.kind==='scan'&&m.to===target.id);
 const galaxySlots=Math.max(0,state.tech.colonization-3),used=galaxyData?.planets.filter(q=>q.owner==='mine').length||0;
 const colonyFlight=f&&galaxyFlight(state,p,remote,start,'starColony');
 return menu+`<div class="page-heading"><span class="eyebrow">GEMEINSAMER RAUM · 10 SYSTEME</span><h1>Galaxiekarte</h1><p>Kolonien und Reservierungen sind für alle Spieler sichtbar. Fernsonden enthüllen Planetentyp und Vorkommen. Dein Tutorial bleibt privat.</p></div>${galaxyError?`<div class="notice">${esc(galaxyError)}</div>`:''}${!cloud?.user?'<div class="notice">Melde dich an, um deinen persönlichen Startplatz und die gemeinsame Galaxie zu laden.</div>':''}<div class="galaxy-toolbar"><label>System<select id="galaxy-system-picker">${systems.map(s=>`<option value="${s.id}" ${selected.id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${button(galaxyBusy?'Wird geladen …':'Galaxie aktualisieren','galaxy-refresh','',galaxyBusy||!cloud?.user)}</div><div class="galaxy-layout"><section class="panel galaxy-map-panel ${galaxyExpanded?'galaxy-expanded':''}" aria-label="Galaxiekarte"><div class="map-viewport" id="galaxy-map" tabindex="0" aria-label="Galaxiekarte: Pfeiltasten verschieben, Plus und Minus zoomen"><div class="map-world">${start?`<button class="galaxy-node tutorial" data-action="galaxy-home" style="left:${start.x}px;top:${start.y}px"><i></i><span class="galaxy-player-label"><strong>${esc(state.systemName||'Mein Sonnensystem')}</strong><small>Dein privates Sonnensystem</small></span></button>`:''}${(galaxyData?.players||[]).filter(q=>!q.is_me).map(q=>`<button class="galaxy-node visited player-marker" aria-label="${esc(q.name)} · ${esc(q.commander)}" title="${esc(q.name)} · ${esc(q.commander)}" data-action="galaxy-player" data-player="${q.id}" style="left:${q.x}px;top:${q.y}px"><i></i><span class="galaxy-player-label"><strong>${esc(q.name)}</strong><small>${esc(q.commander)}</small></span></button>`).join('')}${systems.map(s=>{const known=galaxyData?.planets.some(q=>q.system===s.id&&q.surveyed),occupied=galaxyData?.planets.filter(q=>q.system===s.id&&['mine','foreign'].includes(q.owner))||[],settled=occupied.filter(q=>!q.reserved).length,reserved=occupied.length-settled;return `<button class="galaxy-node ${s.id===selected.id?'selected':''} ${known?'visited':''}" data-action="galaxy-system" data-system="${s.id}" aria-pressed="${s.id===selected.id}" style="left:${s.x}px;top:${s.y}px"><i></i><strong>${esc(s.name)}</strong><small>${s.planetCount?s.planetCount:'3–10'} · ${occupied.length?`${settled} besiedelt${reserved?` · ${reserved} reserviert`:''}`:known?'Untersucht':'Unbesucht'}</small></button>`;}).join('')}</div></div><div class="map-controls">${button(galaxyExpanded?'Großansicht schließen':'Großansicht','galaxy-expand','id="galaxy-expand"')}<button data-map-zoom="out" aria-label="Karte verkleinern">−</button><span id="map-zoom">100 %</span><button data-map-zoom="in" aria-label="Karte vergrößern">+</button><button data-map-zoom="fit">Zentrieren</button></div></section><section class="panel galaxy-detail"><span class="eyebrow">${esc(selected.name)} · ${planets.length||'3–10'} Planeten</span><h2>${target?`P${target.slot} · ${esc(target.surveyed?target.name:'Unbekannt')}`:'System auswählen'}</h2>${target?target.surveyed?`<div class="galaxy-portrait">${orb({...target,buildings:{}},'small')}</div><p>${esc(target.kind)}</p><div class="yields">${RES.map((k,i)=>`<div><span>${LABEL[k]}</span><strong>×${target.mult[i]}</strong></div>`).join('')}</div><p>Energiebedarf ×${target.energy}</p>`:'<div class="unknown">?</div><p>Planetentyp und Vorkommen sind noch unbekannt. Eine Fernsonde liefert den Bericht erst bei Ankunft.</p>':'<p>Die Übersicht zeigt öffentliche Systempositionen. Planetendaten werden vom Server geladen.</p>'}${target?`<p class="galaxy-owner">${galaxyOwnerLabel(target)}</p>`:''}${target?.owner==='foreign'&&!target.reserved&&cloud?.authoritative?button('Angriff planen','pvp-target',`data-to="${target.id}"`):''}${flight}<p class="fine">Fernsonden: ${p.ships.longProbe} · Benötigt Staustrahltriebwerke 1 und Sensortechnik 2.</p>${button(scanPending?'Fernsonde unterwegs':'Fernsonde senden','galaxy-scan',`data-target="${target?.id||''}"`,disabled||!target||scanPending||p.ships.longProbe<1||state.tech.ramjet<1)}${target?.owner==='mine'&&!target.reserved?button('Kolonie öffnen','planet',`data-id="${target.id}"`,!state.planets.some(q=>q.id===target.id)||galaxyBusy):''}${target?.surveyed&&target.owner==='free'?`<p class="fine">Kolonieschiff: ${colonyFlight?duration(colonyFlight.ms)+' · '+colonyFlight.fuel+' Treibstoff':''}. Startmaterial: 350 Metall, 250 Kristall, 100 Treibstoff.</p>${button('Interstellar kolonisieren','galaxy-colony',`data-target="${target.id}"`,disabled||p.ships.starColony<1||used>=galaxySlots)}`:''}<p class="fine">Galaxieplätze: ${used} / ${galaxySlots}. Kolonisierung 4–6 eröffnet zusätzliche Plätze neben den drei Tutorial-Kolonien.</p></section></div>${planets.length?`<section class="panel"><h2>${esc(selected.name)}-System</h2><div class="system-orbits-scroll" tabindex="0" role="region" aria-label="Sonnensystem mit Planeten und Spielernamen; auf kleinen Bildschirmen seitlich verschiebbar"><div class="system-orbits"><img class="central-star" src="./assets/galaxy/star.webp" alt="Zentralstern"><svg viewBox="0 0 1000 360" preserveAspectRatio="none" aria-hidden="true">${planets.map((q,i)=>`<ellipse cx="500" cy="180" rx="${70+i*38}" ry="${35+i*13}"/>`).join('')}</svg>${planets.map((q,i)=>{const angle=(i*137.5+40)*Math.PI/180,x=500+(70+i*38)*Math.cos(angle),y=180+(35+i*13)*Math.sin(angle),ownerLabel=galaxyOwnerLabel(q);return `<button class="orbit-target ${target?.id===q.id?'selected':''} ${q.owner==='mine'?'orbit-mine':q.owner==='foreign'?'orbit-foreign':''} ${q.reserved?'orbit-reserved':''} ${y>290?'label-right':y<180?'label-above':''}" data-action="galaxy-target" data-target="${q.id}" style="left:${x/10}%;top:${y/3.6}%" aria-label="P${q.slot}: ${esc(q.surveyed?q.name:'Unbekannt')} · ${ownerLabel}" title="${ownerLabel}">${q.surveyed?`<img src="${planetImagePath(q)}" alt="">`:'<span>?</span>'}<small class="orbit-label"><span>P${q.slot}${q.reserved?' · reserviert':''}</span>${['mine','foreign'].includes(q.owner)?`<strong class="orbit-commander">${esc(q.commander||(q.owner==='mine'?state.name:'Commander'))}</strong>`:''}</small></button>`;}).join('')}</div></div><div class="galaxy-planet-list">${planets.map(q=>`<button data-action="galaxy-target" data-target="${q.id}" aria-pressed="${q.id===target?.id}"><strong>P${q.slot} · ${esc(q.surveyed?q.name:'Unbekannt')}</strong><small>${galaxyOwnerLabel(q)}${!q.surveyed?' · Nicht untersucht':''}</small></button>`).join('')}</div></section>`:''}${galaxyData?.players?`<section class="panel"><h2>Spieler-Sonnensysteme · ${galaxyData.players.length}</h2><p class="fine">Private Sonnensysteme sind sichtbar, aber für andere Spieler nicht anfliegbar. Dies ist keine Online-Anzeige.</p><div class="galaxy-planet-list">${galaxyData.players.map(q=>button(`${esc(q.name)} · ${esc(q.commander)}${q.is_me?' · Du':''}`,'galaxy-player',`data-player="${q.id}"`)).join('')}</div></section>`:''}${galaxyMissionsHTML()}`;
}
const galaxyMessages={RAMJET_REQUIRED:'Staustrahltriebwerke Stufe 1 fehlen.',SHIP_REQUIRED:'Das passende Schiff fehlt auf dem Startplaneten.',SURVEY_REQUIRED:'Untersuche den Planeten zuerst mit einer Fernsonde.',PLANET_TAKEN:'Dieser Planet wurde inzwischen besiedelt oder reserviert.',COLONY_LIMIT:'Erforsche eine weitere Kolonisierungsstufe für Galaxieplätze.',RESOURCES_REQUIRED:'Lokale Ressourcen reichen nicht für Flug und Startmaterial.',SCAN_UNDERWAY:'Zu diesem Planeten ist bereits eine Fernsonde unterwegs.',GALAXY_COLONIES_REQUIRED:'Diese Sicherung enthält nicht alle deine gemeinsamen Kolonien. Lade den aktuellen Cloud-Spielstand.'};
function galaxyFailure(e){if(e instanceof CloudConflict){cloudBlocked=true;cloudMessage='⚠ Anderes Gerät gespeichert · Cloud neu laden';}const raw=e.message||'Galaxie nicht erreichbar.';return Object.entries(galaxyMessages).find(([key])=>raw.includes(key))?.[1]||raw;}
function adoptGalaxy(result){if(cloud?.authoritative)adoptServer(result);else state=advance(result.state,gameNow());galaxyData=result.galaxy;cloudDirty=false;cloudLastSave=Date.now();cloudMessage='● Galaxie und Cloud abgeglichen';saveGame(state,localStorage,saveKey());localStorage.setItem(saveKey()+'-cloud-meta',JSON.stringify({revision:cloud.revision,pending:false}));}
async function refreshGalaxy(force=false){if(!cloud?.user||!state||cloudBlocked||galaxyBusy||cloudSaving||readOnly||(!force&&Date.now()-galaxyLast<15000))return;const id=cloud.user.id,request=++galaxyRequest;galaxyBusy=true;galaxyError='';try{const data=await cloud.galaxyView();if(request!==galaxyRequest||id!==cloud?.user?.id)return;galaxyData=data;if(!state.galaxy||data.missions.some(m=>m.due<=data.serverNow)){if(!await flushCloud())return;const result=await cloud.galaxySync();if(request!==galaxyRequest||id!==cloud?.user?.id)return;adoptGalaxy(result);}galaxyLast=Date.now();}catch(e){if(request===galaxyRequest)galaxyError=galaxyFailure(e);}finally{if(request===galaxyRequest){galaxyBusy=false;if(tab==='galaxy'||tab==='fleet')render();}}}
async function launchGalaxy(kind,target){if(readOnly||cloudBlocked||galaxyBusy||cloudSaving||!cloud?.user)return;const id=cloud.user.id,request=++galaxyRequest;galaxyBusy=true;galaxyError='';render();try{if(!await flushCloud())return;const result=await cloud.galaxySync({kind,from:state.active,to:target});if(request!==galaxyRequest||id!==cloud?.user?.id)return;adoptGalaxy(result);toast(kind==='scan'?'Fernsonde gestartet.':'Kolonieschiff gestartet; Planet reserviert.');}catch(e){if(request===galaxyRequest){galaxyError=galaxyFailure(e);toast(galaxyError);}}finally{if(request===galaxyRequest){galaxyBusy=false;render();}}}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;switch(b.dataset.action){case 'galaxy-expand':galaxyExpanded=!galaxyExpanded;galaxyCamera=null;render();document.getElementById('galaxy-expand')?.focus();break;case 'galaxy-section':galaxyExpanded=false;galaxySection=b.dataset.section;render();void refreshGalaxy();break;case 'galaxy-system':galaxyExpanded=false;galaxyCamera=null;galaxySystem=b.dataset.system;galaxyTarget='';render();break;case 'galaxy-target':galaxyTarget=b.dataset.target;render();break;case 'galaxy-player':{const q=galaxyData?.players?.find(q=>q.id===b.dataset.player);if(q){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<form method="dialog"><button aria-label="Schließen">×</button></form><h2>${esc(q.name)}</h2><p>Commander: ${esc(q.commander)}${q.is_me?' · Du':''}</p><p>Privates Sonnensystem. Planeten und Spielstand sind geschützt; andere Spieler können hier nicht hinfliegen.</p>`;document.body.append(d);d.showModal();}break;}case 'galaxy-home':document.querySelector('dialog')?.remove();galaxyExpanded=false;galaxyCamera=null;galaxySection='tutorial';render();break;case 'galaxy-refresh':void refreshGalaxy(true);break;case 'galaxy-scan':void launchGalaxy('scan',b.dataset.target);break;case 'galaxy-colony':void launchGalaxy('colony',b.dataset.target);break;}});
app.addEventListener('change',e=>{if(e.target.id==='galaxy-system-picker'){galaxySystem=e.target.value;galaxyTarget='';render();}});
setInterval(()=>{if(state&&cloud?.user&&!document.hidden)void refreshGalaxy();},15000);
function mountMap(){
 const viewport=document.getElementById('galaxy-map');if(!viewport)return null;const world=viewport.querySelector('.map-world');let zoom=galaxyCamera?.zoom||1,base=1,x=galaxyCamera?.x||0,y=galaxyCamera?.y||0,moved=false;const pointers=new Map();
 const apply=()=>{world.style.transform=`translate(${x}px,${y}px) scale(${base*zoom})`;world.style.setProperty('--marker-scale',1/(base*zoom));document.getElementById('map-zoom').textContent=`${Math.round(zoom*100)} %`;galaxyCamera={zoom,x,y};};
 const fit=()=>{zoom=1;base=Math.min(viewport.clientWidth/1000,viewport.clientHeight/1000)*.94;x=(viewport.clientWidth-1000*base)/2;y=(viewport.clientHeight-1000*base)/2;apply();};
 const zoomAt=(value,cx=viewport.clientWidth/2,cy=viewport.clientHeight/2)=>{value=Math.max(.65,Math.min(4,value));const ratio=value/zoom;x=cx-(cx-x)*ratio;y=cy-(cy-y)*ratio;zoom=value;apply();};
 viewport.addEventListener('wheel',e=>{e.preventDefault();const r=viewport.getBoundingClientRect();zoomAt(zoom*Math.exp(-e.deltaY*.001),e.clientX-r.left,e.clientY-r.top);},{passive:false});
 viewport.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});moved=false;});
 viewport.addEventListener('pointermove',e=>{const old=pointers.get(e.pointerId);if(!old)return;const other=[...pointers.entries()].find(([id])=>id!==e.pointerId);if(other){const q=other[1],before=Math.hypot(old.x-q.x,old.y-q.y),after=Math.hypot(e.clientX-q.x,e.clientY-q.y),r=viewport.getBoundingClientRect();if(before>0)zoomAt(zoom*after/before,(e.clientX+q.x)/2-r.left,(e.clientY+q.y)/2-r.top);}else{x+=e.clientX-old.x;y+=e.clientY-old.y;}if(Math.hypot(e.clientX-old.x,e.clientY-old.y)>2){moved=true;viewport.setPointerCapture(e.pointerId);}pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});apply();});
 const end=e=>{pointers.delete(e.pointerId);setTimeout(()=>moved=false,0);};viewport.addEventListener('pointerup',end);viewport.addEventListener('pointercancel',end);viewport.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();}},true);
 viewport.addEventListener('keydown',e=>{const shift={ArrowLeft:[40,0],ArrowRight:[-40,0],ArrowUp:[0,40],ArrowDown:[0,-40]}[e.key];if(shift){e.preventDefault();x+=shift[0];y+=shift[1];apply();}else if(e.key==='+'||e.key==='=')zoomAt(zoom*1.2);else if(e.key==='-')zoomAt(zoom/1.2);});
 viewport.parentElement.querySelectorAll('[data-map-zoom]').forEach(b=>b.addEventListener('click',()=>b.dataset.mapZoom==='fit'?fit():zoomAt(zoom*(b.dataset.mapZoom==='in'?1.2:1/1.2))));
 const saved=galaxyCamera,observer=new ResizeObserver(()=>{if(viewport.clientWidth!==width||viewport.clientHeight!==height){width=viewport.clientWidth;height=viewport.clientHeight;fit();}});let width=viewport.clientWidth,height=viewport.clientHeight;observer.observe(viewport);base=Math.min(viewport.clientWidth/1000,viewport.clientHeight/1000)*.94;if(saved){x=saved.x;y=saved.y;zoom=saved.zoom;apply();}else fit();return ()=>observer.disconnect();
}

function shipOptions(p,freightersOnly=false){return ['freighter','military','civil'].map(category=>`<optgroup label="${{freighter:'Frachter',military:'Kriegsschiffe',defense:'Orbitale Verteidigung',civil:'Sonden & Kolonie'}[category]}">${Object.entries(SHIPS).filter(([key,sh])=>sh.category===category&&(!freightersOnly||isFreighter(key))).map(([key,sh])=>`<option value="${key}" ${key==='transport'?'selected':''}>${esc(sh.name)} · ${p.ships[key]} verfügbar</option>`).join('')}</optgroup>`).join('');}
function shipyardView(p){return `<div class="page-heading"><span class="eyebrow">WERFT AUF ${esc(p.name)} · STUFE ${p.buildings.shipyard}</span><h1>Flotten & Logistik</h1><p>Baue Schiffe hier, stationiere sie auf anderen Welten und verbinde deine Wirtschaft.</p></div><div class="shipyard-controls"><div class="ship-categories" aria-label="Schiffskategorien">${Object.entries({freighter:'Frachter',military:'Kriegsschiffe',civil:'Sonden & Kolonie'}).map(([key,label])=>button(label,'ship-category',`data-category="${key}" aria-pressed="${shipCategory===key}"`)).join('')}</div><p class="fine">${shipCategory==='military'?'Kriegsschiffe können gemeinsame Kolonien angreifen. Unter PvP findest du Kampfwerte und Berichte.':shipCategory==='defense'?'Die Orbitalplattform begrenzt Verteidigung auf 4–16 Plätze. Verteidigungen bleiben auf dieser Welt.':shipCategory==='freighter'?'Kleine Frachter sind schnell, große Frachter transportieren mehr Material pro verbrauchtem Treibstoff.':'Sonden und Kolonieschiffe für dein Tutorial; Fernsonden und interstellare Kolonieschiffe für die gemeinsame Galaxie.'}</p></div><div class="world-grid ships">${Object.entries(SHIPS).filter(([,sh])=>sh.category===shipCategory).map(([key,sh])=>{const info=shipInfo(state,p,key),reason=info.reason||(p.shipjob?'Werft beschäftigt.':'')||(!affordable(p,info.cost)?'Lokale Ressourcen fehlen.':'');return `<article class="panel ship-card"><div class="ship-icon ship-visual"><img src="${sh.asset||'./assets/'+(sh.image||key)+'.webp'}" alt="${esc(sh.name)}" width="768" height="768" loading="lazy" decoding="async"></div><span class="eyebrow">${sh.tier?'TIER '+sh.tier:'BEWÄHRTES SCHIFF'}</span><h2>${sh.name}</h2><p>${sh.role}</p><p>Im Orbit: <strong>${p.ships[key]}</strong>${isFreighter(key)?` · ${fmt(cargoCapacity(state,1,key))} Laderaum`:''}</p><p class="fine">Tempo ×${sh.speed.toLocaleString('de-DE')} · ${sh.fuel} Treibstoff / Entfernungseinheit / Schiff vor Forschung</p><div class="cost">${costHTML(info.cost)}<span>◷ ${duration(info.ms)} / Schiff</span></div><p class="fine">Werft ${sh.shipyard||1} · ${TECHS[sh.tech].name} ${sh.techLevel||1} · ${TECHS[sh.engine||'drive'].name} ${sh.engineLevel||0}</p>${reason?`<p class="requirement">${esc(reason)}</p>`:''}<label class="ship-build-count">Anzahl<input id="build-count-${key}" type="number" min="1" max="50" step="1" value="1" aria-label="Anzahl ${sh.name}"></label>${button('Bauen','ship',`data-key="${key}"`,reason||readOnly)}</article>`;}).join('')}</div>${p.shipjob?progress(p.shipjob,`${p.shipjob.count} × ${SHIPS[p.shipjob.key].name}`):''}`;}
function fleetReports(){return `<section class="panel"><h2>Berichte</h2>${state.reports.length?state.reports.slice(0,20).map(r=>`<article class="report"><div class="split"><strong>${esc(r.title)}</strong><time>${new Date(r.time).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</time></div><p>${esc(r.body)}</p></article>`).join(''):'<p class="muted">Deine Entdeckungen und Lieferungen erscheinen hier.</p>'}</section>`;}
function fleetOrderFields(prefix='',values=null){return RES.map(k=>`<label>${LABEL[k]}<input name="${prefix}${k}" value="${values?.[k]??0}" inputmode="numeric" pattern="[0-9]+|[mM][aA][xX]" required aria-label="${prefix}${LABEL[k]}: Menge oder max"><small>Ganze Menge oder max</small></label>`).join('');}
function planetOptions(selected,exclude=''){return state.planets.filter(q=>q.id!==exclude).map(q=>`<option value="${q.id}" ${q.id===selected?'selected':''}>${esc(q.name)}</option>`).join('');}
function amountControl(name,value,label,allowMax=true){return `<div class="amount-control"><div class="amount-stepper"><input name="${name}" value="${value}" inputmode="numeric" pattern="${allowMax?'[0-9]+|[mM][aA][xX]':'[0-9]+'}" required aria-label="${esc(label)}"></div>${allowMax?`<div class="amount-shortcuts"><button type="button" data-action="amount-set" data-value="0">0</button><button type="button" data-action="amount-step" data-delta="100">+100</button><button type="button" data-action="amount-step" data-delta="500">+500</button><button type="button" data-action="amount-set" data-value="max">MAX</button></div>`:''}</div>`;}
function routeStopRow(id,first=false,stop=null){const q=getPlanet(state,id),load=stop?.load||vector([0,0,0]),unload=stop?.unload||(first?vector([0,0,0]):{metal:'max',crystal:'max',fuel:'max'});return `<fieldset class="route-stop"><legend>${first?'Startplanet':'Stopp'}</legend><details open><summary>${orb(q,'small')}<strong>${esc(q.name)}</strong><span>Bearbeiten</span></summary><div class="stop-content"><label>Planet<select name="stop-planet" ${first?'disabled':''}>${planetOptions(id)}</select></label>${first?'':`<div class="stop-tools"><button type="button" data-action="move-stop" data-dir="-1" aria-label="Stopp nach vorne">←</button><button type="button" data-action="move-stop" data-dir="1" aria-label="Stopp nach hinten">→</button><button type="button" data-action="remove-stop">Entfernen</button></div>`}<div class="stop-matrix"><div class="matrix-head">Rohstoff</div><div class="matrix-head">↓ Abladen</div><div class="matrix-head">↑ Einladen</div>${RES.map(k=>`<label class="resource-name">${ICON[k]} ${LABEL[k]}<small>Bestand: <span data-stock="${k}">${fmt(q.resources[k]+q.depot[k])}</span></small></label>${amountControl('unload-'+k,unload[k],LABEL[k]+' abladen')}${amountControl('load-'+k,load[k],LABEL[k]+' einladen')}`).join('')}</div></div></details></fieldset>`;}
function manifestText(m){return Object.entries(fleetManifest(m)).map(([k,n])=>`${n} × ${SHIPS[k].name}`).join(' + ');}
function readMixedFleet(form){return Object.fromEntries([...form.querySelectorAll('[data-fleet-ship]')].map(el=>[el.dataset.fleetShip,Number(el.value)]).filter(([,n])=>n!==0));}
function routeSubmenu(){return `<div class="route-submenu" role="tablist" aria-label="Handelsrouten-Menü">${[['existing','≡ Bestehende Routen'],['new','+ Neue Route']].map(([key,label])=>`<button type="button" role="tab" id="route-tab-${key}" aria-controls="route-content" aria-selected="${routeSection===key}" tabindex="${routeSection===key?0:-1}" data-action="route-${key}">${label}</button>`).join('')}</div>`;}
function routeMatches(m){const status=m.stopping?'ending':m.to===m.home?'return':'outbound';const words=[m.name,manifestText(m),...m.stops.map(q=>getPlanet(state,q.planet).name)].join(' ').toLocaleLowerCase('de-DE');return words.includes(routeQuery.toLocaleLowerCase('de-DE').trim())&&(routeFilter==='all'||routeFilter===status||routeFilter==='pending'&&!!m.pending);}
function routeCard(m){const fleet=fleetManifest(m),returning=m.to===m.home,status=m.stopping?'Endet nach dieser Runde':returning?'Rückkehr':'Unterwegs',percent=Math.round(Math.min(100,Math.max(0,100*(state.time-m.start)/m.duration)));return `<article class="trade-route route-card" data-route-card="${m.id}" ${routeMatches(m)?'':'hidden'}><div class="route-card-heading"><h3>${esc(m.name)}</h3><span class="route-status ${m.stopping?'ending':returning?'returning':''}">${status}</span><span class="route-round">Runde ${m.rounds+1} · ${m.repeat?'Endlos':'Eine Runde'}</span></div><div class="route-path" aria-label="Flugreihenfolge">${[...m.stops.map(q=>q.planet),m.home].map((id,i)=>`${i?'<span class="route-arrow" aria-hidden="true">→</span>':''}<div class="route-world">${orb(getPlanet(state,id),'small')}<span>${esc(getPlanet(state,id).name)}</span></div>`).join('')}</div><div class="route-freight"><div class="route-ships">${Object.entries(fleet).map(([k,n])=>`<span><img src="./assets/${SHIPS[k].image||k}.webp" alt=""><strong>${n} × ${esc(SHIPS[k].name)}</strong></span>`).join('')}</div><div class="route-cargo-metrics"><div><strong>${fmt(fleetCapacity(state,fleet))}</strong><small>Laderaum</small></div><div><strong>${costHTML(m.cargo)||'Leer'}</strong><small>Aktuelle Fracht</small></div></div></div><div class="route-travel"><div class="route-next">Nächster Stopp: <strong>${esc(getPlanet(state,m.to).name)}</strong></div><div class="route-flight-progress" role="progressbar" aria-label="Fortschritt zur nächsten Welt" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" data-route-progress="${m.id}"><i style="width:${percent}%"></i></div><div class="route-arrival">Ankunft in <strong data-due="${m.due}">${duration(m.due-state.time)}</strong></div><div class="route-actions">${button('✎ Bearbeiten','route-edit',`data-id="${m.id}" aria-label="Route ${esc(m.name)} bearbeiten"`,m.stopping||readOnly)}${button(m.stopping?'Beendigung vorgemerkt':'Beenden','stop-route',`data-id="${m.id}" aria-label="Route ${esc(m.name)} beenden"`,m.stopping||readOnly)}</div></div>${m.pending?`<div class="route-pending"><span>◷ Änderung vorgemerkt · bei Rückkehr nach ${esc(getPlanet(state,m.home).name)}</span>${button('Verwerfen','cancel-route-edit',`data-id="${m.id}" aria-label="Vormerkung für ${esc(m.name)} verwerfen"`,readOnly)}</div>`:''}</article>`;}
function routeOverview(routes){return `<section class="route-dashboard"><div class="route-dashboard-heading"><div><h2>Deine Handelsrouten <span class="route-total">${routes.length}</span></h2><p class="fine">Sparflug: +25 % Flugzeit · −25 % Treibstoff je Strecke.</p></div><div class="route-filters"><label class="route-search">Route suchen<input id="route-search" type="search" value="${esc(routeQuery)}" placeholder="Name, Planet oder Schiff …"></label><label>Status<select id="route-filter">${[['all','Alle Routen'],['outbound','Unterwegs'],['return','Rückkehr'],['pending','Änderung vorgemerkt'],['ending','Wird beendet']].map(([key,label])=>`<option value="${key}" ${routeFilter===key?'selected':''}>${label}</option>`).join('')}</select></label></div></div><div class="route-cards">${routes.map(routeCard).join('')}</div><div id="route-no-results" class="panel route-empty" ${routes.some(routeMatches)?'hidden':''}><h3>${routes.length?'Keine passende Route':'Noch keine Handelsrouten'}</h3><p>${routes.length?'Ändere die Suche oder den Statusfilter.':'Verbinde deine Welten mit einer regelmäßigen Versorgung.'}</p>${routes.length?'':button('+ Erste Route erstellen','route-new')}</div></section>`;}
function filterRouteCards(){const routes=state.missions.filter(m=>m.type==='route');for(const el of document.querySelectorAll('[data-route-card]')){const m=routes.find(m=>m.id===Number(el.dataset.routeCard));el.hidden=!m||!routeMatches(m);}const empty=document.getElementById('route-no-results');if(empty)empty.hidden=routes.some(routeMatches);}
function tradeRoutes(p){const routes=state.missions.filter(m=>m.type==='route'),editing=routeSection==='existing'?routes.find(m=>m.id===routeEditId):null,model=editing?.pending||editing,home=editing?getPlanet(state,editing.home):p,old=editing?fleetManifest(editing):{},fleet=model?(model.fleet||fleetManifest(model)):{},stops=model?.stops||[{planet:home.id,load:vector([0,0,0]),unload:vector([0,0,0])},{planet:state.planets.find(q=>q.id!==home.id)?.id,load:vector([0,0,0]),unload:{metal:'max',crystal:'max',fuel:'max'}}];return `${routeSubmenu()}<div id="route-content" role="tabpanel" aria-labelledby="route-tab-${routeSection}">${routeSection==='existing'&&!editing?routeOverview(routes):`<section class="panel trade-editor"><div class="split"><h2>${editing?'Route bearbeiten · '+esc(editing.name):'Neue Handelsroute'}</h2>${button('← Zur Routenübersicht','route-existing')}</div>${state.planets.length<2?'<p>Besiedle eine zweite Welt, um Handelsrouten anzulegen.</p>':`<form id="route-form" data-planet="${home.id}" data-route-id="${editing?.id||0}"><div class="form-grid"><label>Routenname<input name="name" maxlength="40" required value="${esc(model?.name||'Handelsroute')}"></label><label>Betrieb<select name="repeat"><option value="true" ${model?.repeat===false?'':'selected'}>Endlos wiederholen</option><option value="false" ${model?.repeat===false?'selected':''}>Eine Runde</option></select></label></div><details class="mixed-fleet-picker" open><summary>Flotte zusammenstellen · Startplanet ${esc(home.name)}</summary><p class="fine">Vorgemerkte Schiffe bleiben bis zum Wechsel für andere Aufträge verfügbar.</p><div class="mixed-fleet-list">${Object.entries(SHIPS).filter(([k])=>isFreighter(k)).map(([k,sh])=>{const available=home.ships[k]+(old[k]||0);return `<div class="mixed-ship"><img src="./assets/${sh.image||k}.webp" alt="${esc(sh.name)}"><div><strong>${esc(sh.name)}</strong><small>${home.ships[k]} im Orbit${old[k]?` + ${old[k]} in dieser Route`:''} · ${fmt(cargoCapacity(state,1,k))} Laderaum / Schiff</small></div><div class="amount-control"><div class="amount-stepper"><button type="button" data-action="amount-step" data-delta="-1" aria-label="${sh.name} verringern">−</button><input name="fleet-${k}" data-fleet-ship="${k}" type="number" min="0" max="100" step="1" value="${fleet[k]||0}" aria-label="Anzahl ${sh.name}"><button type="button" data-action="amount-step" data-delta="1" aria-label="${sh.name} erhöhen">+</button></div><button type="button" class="all-ships" data-action="amount-set" data-value="${Math.min(100,available)}">Alle verfügbaren</button></div></div>`;}).join('')}</div></details><div class="route-estimate" id="route-estimate" role="status"></div><h3>Stopps in Flugreihenfolge</h3><p class="fine">Erst abladen, dann einladen. Nach dem letzten Stopp kehrt die Flotte zum Startplanet zurück und lädt vollständig ab.</p><div id="route-stops" class="route-stops">${stops.map((q,i)=>routeStopRow(q.planet,i===0,q)).join('')}</div><button type="button" data-action="add-stop">+ Stopp hinzufügen</button><p class="fine">+100 und +500 addieren bei jedem Klick. Nach MAX beginnt eine feste Menge wieder bei 0. MAX bleibt dynamisch: verfügbare Menge bis zum freien Laderaum. Ladereihenfolge: Metall → Kristall → Treibstoff. Bestände sind aktuelle Vorschauen, geladen wird bei Ankunft.</p>${editing?'<div class="pending-change">Änderungen werden gemeinsam bei Rückkehr zum Startplanet aktiviert. Fehlen Schiffe, bleibt die bisherige Route aktiv und die Änderung vorgemerkt.</div>':''}<div class="trade-save"><button type="submit" ${readOnly?'disabled':''}>${editing?'Änderungen vormerken':'Handelsroute starten'}</button>${editing?button('Zur Routenübersicht','route-existing'):''}</div></form>`}</section>`}</div>`;}
function fleetMissions(missions){return missions.map(m=>`<article class="mission"><div class="split"><strong>${esc(m.type==='route'?m.name:({station:'Stationieren',collect:'Abholen',deliver:'Liefern',transport:'Liefern',probe:'Erkundung',colony:'Kolonisierung'}[m.type]))} · ${esc(manifestText(m))}</strong><span data-due="${m.due}">${duration(m.due-state.time)}</span></div><p>${esc(getPlanet(state,m.from).name)} ${m.phase==='return'?'←':'→'} ${esc((state.planets.find(q=>q.id===m.to)||TARGETS.find(q=>q.id===m.to)).name)}${m.type==='route'?` · Runde ${m.rounds+1}`:''}</p><div class="cost">${costHTML(m.cargo)}</div>${m.type==='route'?`<p class="fine">${m.stops.map(q=>esc(getPlanet(state,q.planet).name)).join(' → ')} → ${esc(getPlanet(state,m.home).name)}</p>${button(m.stopping?'Endet nach dieser Runde':'Route nach dieser Runde beenden','stop-route',`data-id="${m.id}"`,m.stopping||readOnly)}`:''}</article>`).join('')||'<p class="muted">Keine Flotten unterwegs.</p>'; }
function fleetMenu(){return `<div class="fleet-menu" role="tablist" aria-label="Flottenbereiche">${Object.entries(fleetSections).map(([key,[icon,label,description]])=>`<button type="button" role="tab" id="fleet-tab-${key}" aria-controls="fleet-pane-${key}" aria-selected="${fleetSection===key}" tabindex="${fleetSection===key?0:-1}" data-action="fleet-section" data-section="${key}"><span class="fleet-menu-icon" aria-hidden="true">${icon}</span><span><strong>${label}</strong><small>${description}</small></span>${key==='routes'&&state.missions.some(m=>m.type==='route')?`<span class="fleet-menu-count">${state.missions.filter(m=>m.type==='route').length}</span>`:''}</button>`).join('')}</div>`;}
function fleetPane(key){return `<div class="fleet-pane" role="tabpanel" id="fleet-pane-${key}" aria-labelledby="fleet-tab-${key}" ${fleetSection!==key?'hidden':''}>`;}
function fleet(p){
 if(fleetSection==='pvp')return fleetMenu()+fleetPane('pvp')+pvpView(state,cloud?.pvp,galaxyData,galaxyBusy||cloudSaving,pvpDraft)+'</div>';
 const head=shipyardView(p);
 const split=head.indexOf('<div class="shipyard-controls">');
 return head.slice(0,split).replace('Schiffe sind während des gesamten Hin- und Rückflugs gebunden.','Baue Schiffe hier, stationiere sie auf anderen Welten und verbinde deine Wirtschaft.')+fleetMenu()+fleetPane('hangar')+head.slice(split)+`
 <section class="panel"><h2>Hangar & Flotten im Orbit · ${esc(p.name)}</h2><div class="chips">${Object.entries(SHIPS).map(([k,sh])=>`<span>${sh.icon} ${p.ships[k]} × ${sh.name}</span>`).join('')}</div><p class="fine">Verfügbar zum Start. Unterwegs gebundene Schiffe erscheinen in der Gesamtübersicht.</p></section>
 </div>${fleetPane('orders')}<section class="panel"><h2>Flottenauftrag</h2>${state.planets.length<2?'<p>Besiedle eine weitere Welt, um Flotten zu verlegen und Handelsrouten anzulegen.</p>':`<form id="fleet-order-form" data-planet="${p.id}"><div class="form-grid"><label>Auftrag<select name="type"><option value="deliver">Liefern und zurückkehren</option><option value="collect">Abholen und zurückkehren</option><option value="station">Stationieren (mit optionaler Ladung)</option></select></label><label>Zielplanet<select name="to">${planetOptions('',p.id)}</select></label><label>Schiffstyp<select name="ship">${shipOptions(p)}</select></label><label>Anzahl<input name="count" type="number" min="1" max="100" value="1" required></label>${fleetOrderFields()}</div><p class="fine" id="fleet-estimate"></p><p class="fine">Bei Abholen wird erst bei Ankunft geladen. „max“ füllt den freien Laderaum mit verfügbaren Beständen. Priorität: Metall → Kristall → Treibstoff. Sonden, Kolonieschiffe und Kriegsschiffe können ohne Ladung stationiert werden.</p><button ${readOnly?'disabled':''}>Flotte starten →</button></form>`}</section>
 <section class="panel"><h2>Lokale Materialreserve</h2><p class="fine">Diese Mengen bleiben bei Flottenbeladung auf ${esc(p.name)}. Bau und Forschung dürfen sie verwenden.</p><form id="reserve-form" data-planet="${p.id}"><div class="form-grid">${RES.map(k=>`<label>${LABEL[k]}<input name="${k}" type="number" min="0" max="1000000000000" step="1" value="${p.reserves?.[k]||0}" required></label>`).join('')}</div><button ${readOnly?'disabled':''}>Reserven speichern</button></form></section>
 </div>${fleetPane('routes')}${tradeRoutes(p)}
 </div>${fleetPane('overview')}<section class="panel"><h2>Gesamte Flotte</h2><div class="ranking-scroll"><table class="ranking-table"><thead><tr><th>Im Orbit</th>${Object.values(SHIPS).map(sh=>`<th>${sh.name}</th>`).join('')}</tr></thead><tbody>${state.planets.map(q=>`<tr><th>${esc(q.name)}</th>${Object.keys(SHIPS).map(k=>`<td>${q.ships[k]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h3>Unterwegs · ${state.missions.length}</h3>${fleetMissions(state.missions)}${galaxyMissionsHTML()}</section>`+fleetReports()+'</div>';
}
function fleetDraftKey(planet){return `${cloud?.user?.id||'guest'}:${planet}`;}
function captureFleetDraft(){for(const id of ['fleet-order-form','route-form','reserve-form']){const form=document.getElementById(id);if(!form)continue;const key=fleetDraftKey(form.dataset.planet)+(id==='route-form'?':route:'+form.dataset.routeId:''),draft=fleetDrafts.get(key)||{};draft[id]={fields:[...form.elements].filter(el=>el.name).map(el=>({name:el.name,value:el.value})),stops:id==='route-form'?readRouteStops(form):null};fleetDrafts.set(key,draft);}}
function restoreFleetDraft(){for(const id of ['fleet-order-form','route-form','reserve-form']){const form=document.getElementById(id);if(!form)continue;const key=fleetDraftKey(form.dataset.planet)+(id==='route-form'?':route:'+form.dataset.routeId:''),saved=fleetDrafts.get(key)?.[id];if(!saved)continue;if(saved.stops)form.querySelector('#route-stops').innerHTML=saved.stops.map((stop,i)=>routeStopRow(stop.planet,i===0,stop)).join('');const seen={};for(const field of saved.fields){const i=seen[field.name]||0;seen[field.name]=i+1;const el=form.querySelectorAll(`[name="${field.name}"]`)[i];if(el)el.value=field.value;}}}
function orderValue(v){const x=String(v).trim().toLowerCase();return x==='max'?'max':x!==''?Number(x):NaN;}
function readRouteStops(form){return [...form.querySelectorAll('.route-stop')].map(row=>({planet:row.querySelector('[name="stop-planet"]').value,load:Object.fromEntries(RES.map(k=>[k,orderValue(row.querySelector(`[name="load-${k}"]`).value)])),unload:Object.fromEntries(RES.map(k=>[k,orderValue(row.querySelector(`[name="unload-${k}"]`).value)]))}));}
function fleetEstimates(){
 if(!state)return;const p=getPlanet(state,state.active),form=document.getElementById('fleet-order-form');
 if(form){let d=new FormData(form);const type=d.get('type'),shipSelect=form.querySelector('[name="ship"]');for(const option of shipSelect.options)option.disabled=type!=='station'&&!isFreighter(option.value);if(type!=='station'&&!isFreighter(shipSelect.value)){shipSelect.value='transport';d=new FormData(form);}const ship=d.get('ship'),to=state.planets.find(q=>q.id===d.get('to')),count=Number(d.get('count'));if(to&&count>0){const interstellar=(p.system||'tutorial')!==(to.system||'tutorial'),submit=form.querySelector('button:not([type=button])');if(interstellar&&!SHIPS[ship].engine){document.getElementById('fleet-estimate').textContent='Diese Strecke benötigt einen Frachter bzw. ein Schiff mit Staustrahl-, Impuls- oder Hyperraumtriebwerken.';if(submit)submit.disabled=true;}else{if(submit)submit.disabled=readOnly||p.ships[ship]<count;const f=legInfo(state,p,to,count,ship);document.getElementById('fleet-estimate').textContent=`${fmt(cargoCapacity(state,count,ship))} Laderaum · ${duration(f.ms)} je Strecke · ${f.fuel*(type==='station'?1:2)} Treibstoff insgesamt`;}}}
 const route=document.getElementById('route-form');if(route){const output=document.getElementById('route-estimate'),submit=route.querySelector('[type=submit]');try{const fleet=checkedFleet(readMixedFleet(route)),stops=readRouteStops(route),home=getPlanet(state,route.dataset.planet);if(stops.length<2||stops.some((q,i)=>q.planet===stops[(i+1)%stops.length].planet))throw Error('Mindestens zwei Stopps, keine direkt aufeinanderfolgenden gleichen Planeten.');const f=routeInfo(state,stops,fleet),missing=Object.entries(fleet).some(([k,n])=>home.ships[k]<n),editing=Number(route.dataset.routeId)>0;output.innerHTML=`<div class="trade-metrics"><span><strong>${Object.values(fleet).reduce((a,b)=>a+b,0)}</strong> Schiffe</span><span><strong>${fmt(f.capacity)}</strong> Laderaum</span><span><strong>${duration(f.ms)}</strong> je Runde</span><span><strong>${f.fuel}</strong> Treibstoff / Runde</span></div><p class="fine">${SHIPS[f.slowest].name} bestimmt das Flottentempo. Forschungsboni und Sparflug sind berücksichtigt.</p>${missing?`<p class="${editing?'pending-change':'requirement'}">${editing?'Verfügbarkeit wird bei Rückkehr geprüft.':'Nicht genügend Schiffe am Startplanet.'}</p>`:''}`;submit.disabled=readOnly||cloudBlocked||(!editing&&missing);for(const row of route.querySelectorAll('.route-stop')){const q=getPlanet(state,row.querySelector('[name=stop-planet]').value);row.querySelector('summary').innerHTML=`${orb(q,'small')}<strong>${esc(q.name)}</strong><span>Bearbeiten</span>`;for(const k of RES)row.querySelector(`[data-stock="${k}"]`).textContent=fmt(q.resources[k]+q.depot[k]);}}catch(e){output.textContent=e.message;submit.disabled=true;}}

}
app.addEventListener('submit',e=>{if(!['fleet-order-form','route-form','reserve-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='reserve-form')command({type:'reserve',reserves:Object.fromEntries(RES.map(k=>[k,Number(f.get(k))]))});else if(e.target.id==='route-form')command({type:Number(e.target.dataset.routeId)?'edit-route':'route',id:Number(e.target.dataset.routeId),planet:e.target.dataset.planet,name:f.get('name'),fleet:readMixedFleet(e.target),repeat:f.get('repeat')==='true',stops:readRouteStops(e.target)});else command({type:f.get('type'),ship:f.get('ship'),to:f.get('to'),count:Number(f.get('count')),order:Object.fromEntries(RES.map(k=>[k,orderValue(f.get(k))]))});});
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;if(b.dataset.action==='ship-category'){shipCategory=b.dataset.category;render();return;}if(b.dataset.action==='fleet-section'){fleetSection=b.dataset.section;render();if(fleetSection==='pvp')void refreshGalaxy(true);return;}if(['route-new','route-edit','route-existing'].includes(b.dataset.action)){captureFleetDraft();document.getElementById('route-form')?.remove();routeSection=b.dataset.action==='route-new'?'new':'existing';routeEditId=b.dataset.action==='route-edit'?Number(b.dataset.id):0;render();document.querySelector('.route-submenu')?.scrollIntoView({behavior:'smooth',block:'start'});return;}if(b.dataset.action==='cancel-route-edit'){command({type:'cancel-route-edit',id:Number(b.dataset.id)});return;}if(b.dataset.action==='stop-route')command({type:'stop-route',id:Number(b.dataset.id)});if(readOnly||cloudBlocked)return;if(b.dataset.action==='amount-set'||b.dataset.action==='amount-step'){const input=b.closest('.amount-control').querySelector('input');const old=orderValue(input.value);input.value=b.dataset.action==='amount-set'?b.dataset.value:Math.max(0,Math.min(input.dataset.fleetShip?100:1e12,(old==='max'?0:old||0)+Number(b.dataset.delta)));input.dispatchEvent(new Event('input',{bubbles:true}));return;}if(b.dataset.action==='move-stop'){const row=b.closest('.route-stop'),rows=[...row.parentElement.children],i=rows.indexOf(row),dir=Number(b.dataset.dir);if(i>0&&i+dir>0&&i+dir<rows.length){if(dir<0)row.parentElement.insertBefore(row,rows[i-1]);else row.parentElement.insertBefore(rows[i+1],row);}fleetEstimates();return;}if(b.dataset.action==='add-stop'){const rows=document.querySelectorAll('.route-stop');if(rows.length>=12){toast('Maximal 12 Stopps.');return;}const last=rows[rows.length-1].querySelector('select').value;document.getElementById('route-stops').insertAdjacentHTML('beforeend',routeStopRow((state.planets.find(q=>q.id!==last&&q.id!==state.active)||state.planets.find(q=>q.id!==last)).id));fleetEstimates();}else if(b.dataset.action==='remove-stop'){b.closest('.route-stop').remove();fleetEstimates();}});
app.addEventListener('keydown',e=>{const button=e.target.closest('[data-action="fleet-section"]');if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=Object.keys(fleetSections),index=keys.indexOf(button.dataset.section);fleetSection=e.key==='Home'?keys[0]:e.key==='End'?keys[keys.length-1]:keys[(index+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length];render();document.getElementById(`fleet-tab-${fleetSection}`).focus();});
app.addEventListener('keydown',e=>{const b=e.target.closest('[data-action="route-existing"], [data-action="route-new"]');if(!b||b.getAttribute('role')!=='tab'||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();captureFleetDraft();document.getElementById('route-form')?.remove();routeSection=e.key==='Home'?'existing':e.key==='End'?'new':routeSection==='existing'?'new':'existing';routeEditId=0;render();document.getElementById('route-tab-'+routeSection)?.focus();});
app.addEventListener('input',e=>{if(e.target.id==='route-search'){routeQuery=e.target.value;filterRouteCards();return;}if(e.target.closest('#fleet-order-form, #route-form')){e.target.closest('.amount-control')?.classList.toggle('max-active',String(e.target.value).toLowerCase()==='max');fleetEstimates();}});
app.addEventListener('change',e=>{if(e.target.id==='route-filter'){routeFilter=e.target.value;filterRouteCards();return;}if(e.target.closest('#fleet-order-form, #route-form')){e.target.closest('.amount-control')?.classList.toggle('max-active',String(e.target.value).toLowerCase()==='max');fleetEstimates();}});

let rankingRows=[],rankingBusy=false,rankingError='',rankingTime=0,rankingRequest=0;
function leaderboard(){
 const intro='<div class="page-heading"><span class="eyebrow">WaHueLaPa Universe · Commander</span><h1>Rangliste</h1><p>Wer baut das stärkste Imperium?</p></div>';
 if(!cloud?.user)return intro+'<section class="panel"><h2>Gemeinsam vergleichen</h2><p>Melde dich an und speichere dein Imperium in der Cloud, um dabei zu sein.</p>'+button('Anmelden / Konto erstellen','settings')+'</section>';
 return intro+`<section class="panel"><div class="split"><div><h2>Imperiumspunkte</h2><p class="fine">${rankingTime?'Abgerufen '+new Date(rankingTime).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'}):'Stand: letzter Cloud-Spielstand je Commander'}</p></div>${button(rankingBusy?'Lädt …':'Aktualisieren','ranking-refresh','',rankingBusy)}</div>${rankingError?`<p class="requirement" role="status">${esc(rankingError)}</p>`:''}${rankingError.includes('leaderboard.sql')?'<p><a href="https://github.com/Cimera311/Wahuelapa-Universe/blob/main/supabase/leaderboard.sql" target="_blank" rel="noopener">SQL-Erweiterung öffnen</a></p>':''}${rankingRows.length?`<div class="ranking-scroll"><table class="ranking-table"><caption class="fine">Top 100 und dein eigener Rang · gleiche Punkte teilen einen Rang</caption><thead><tr><th scope="col">Rang</th><th scope="col">Commander</th><th scope="col">Punkte</th><th scope="col">Kolonien</th></tr></thead><tbody>${rankingRows.map(r=>`<tr class="${r.is_me?'ranking-me':''}"><td>${fmt(r.rank)}</td><th scope="row">${esc(r.commander)}${r.is_me?' <span class="cyan">· Du</span>':''}</th><td><strong>${fmt(r.points)}</strong><small>Gebäude ${fmt(r.building_points)} · Forschung ${fmt(r.research_points)} · Flotte ${fmt(r.fleet_points)}</small></td><td>${fmt(r.colonies)}</td></tr>`).join('')}</tbody></table></div>`:!rankingBusy&&!rankingError?'<p class="muted">Noch keine Imperien gespeichert. Speichere deinen Cloud-Spielstand, um den Anfang zu machen.</p>':rankingBusy?'<p class="muted" role="status">Rangliste wird geladen …</p>':''}</section><section class="panel"><h2>So entstehen deine Punkte</h2><p>Je 100 verbaute Ressourcen ergeben einen Punkt. Es zählen die Kosten aller abgeschlossenen Gebäudestufen, Forschungen und deiner vorhandenen Schiffe. Flotten unterwegs zählen mit. Lagerbestände und laufende Bauaufträge zählen nicht.</p><p class="fine">Die drei Bereiche werden einzeln abgerundet und addiert. Startgebäude zählen ebenfalls. Die Rangliste zeigt den zuletzt gespeicherten Cloud-Stand; sie aktualisiert sich beim Öffnen und über „Aktualisieren“. Commander-Namen und Ranglistenwerte sind für angemeldete Spieler sichtbar.</p></section>`;
}
async function refreshRanking(force=false){
 if(rankingBusy||!cloud?.user||(!force&&Date.now()-rankingTime<15000))return;
 const request=++rankingRequest,account=cloud.user.id;rankingBusy=true;rankingError='';if(tab==='leaderboard')render();
 try{const rows=await cloud.leaderboard();if(request!==rankingRequest||cloud?.user?.id!==account)return;rankingRows=rows;rankingTime=Date.now();}catch(e){if(request===rankingRequest&&cloud?.user?.id===account)rankingError=e.message||'Rangliste nicht erreichbar. Bitte erneut versuchen.';}finally{if(request===rankingRequest){rankingBusy=false;if(tab==='leaderboard')render();}}
}
function clearRanking(){routeEditId=0;routeSection='existing';routeQuery='';routeFilter='all';clearGalaxy();rankingRequest++;rankingRows=[];rankingBusy=false;rankingError='';rankingTime=0;}
function render(){captureFleetDraft();if(!state){app.innerHTML=`<main class="welcome"><div class="brand">WaHueLaPa<span>Universe</span></div>${orb({color:'#53add3',kind:'Heimatplanet',buildings:{}})}<section class="panel"><span class="eyebrow">SOLO · VERSION 0.1</span><h1>Deine erste Welt.</h1><p>Erkunde fremde Planeten, spezialisiere Kolonien und verbinde sie mit deiner Transportflotte.</p><form id="start-form"><label>Dein Commander-Name<input name="name" maxlength="30" placeholder="z. B. Sebastian" required autocomplete="nickname"></label><button ${readOnly?'disabled':''}>Imperium gründen →</button></form><p class="fine">Als Gast wird dein Fortschritt automatisch in diesem Browser gespeichert.</p>${CLOUD_CONFIG.enabled?button('Anmelden / Konto erstellen','settings'):''}</section></main>`;return;}
 const p=getPlanet(state,state.active),z=stats(state,p);app.innerHTML=`<header><div class="topbar"><button class="brand plain" data-action="tab" data-tab="overview">WaHueLaPa<span>Universe</span></button><div class="commander">${esc(state.name)} <button class="plain gear" data-action="settings" aria-label="Spielstand und Hilfe">⚙</button></div></div><div class="resources">${RES.map(k=>`<div><span class="resource-icon">${ICON[k]}</span><div><small>${LABEL[k]}</small><strong data-resource="${k}">${fmt(p.resources[k])}</strong><small>${fmt(z.rates[k])}/Std · Lager ${fmt(z.cap)}</small></div></div>`).join('')}<div><span class="resource-icon amber">ϟ</span><div><small>Energie</small><strong class="${z.supply-z.demand<0?'amber':''}">${Math.round(z.supply-z.demand)>0?'+':''}${Math.round(z.supply-z.demand)}</strong><small>${Math.round(z.supply)} / ${Math.round(z.demand)}</small></div></div></div><div class="planet-bar"><label>Aktive Welt <select id="planet-select">${state.planets.map(q=>`<option value="${q.id}" ${q.id===p.id?'selected':''}>${esc(q.name)} · [${esc(q.coord)}]</option>`).join('')}</select></label><span class="local-badge">${readOnly?'Nur Ansicht · anderer Tab aktiv':cloudBadge()}</span></div></header><main>${cloud?.pvp?.incoming?.length?`<div class="notice" role="alert">⚠ ${cloud.pvp.incoming.length} Angriff(e) unterwegs. ${button('Warnungen ansehen','pvp-open')}</div>`:''}${RES.some(k=>p.depot[k]>0)?`<div class="notice">Lieferdepot: ${costHTML(p.depot)}. Wird automatisch übernommen, sobald Lagerplatz frei ist.</div>`:''}${({overview,build:buildings,research,galaxy,fleet,leaderboard}[tab])(p)}<footer>Prototyp-Balancing: kurze Zeiten zum Ausprobieren. PvP-Kämpfe werden serverseitig verarbeitet. Rangliste: zuletzt gespeicherte Cloud-Spielstände.</footer></main><nav aria-label="Hauptnavigation">${Object.entries(tabs).map(([key,[icon,label]])=>`<button class="${key===tab?'active':''}" data-action="tab" data-tab="${key}"><span>${icon}</span>${label}</button>`).join('')}</nav>`;if(tab==='fleet')restoreFleetDraft();transportEstimate();fleetEstimates();mapCleanup?.();mapCleanup=tab==='galaxy'?mountMap():null;}
function transportEstimate(){const form=document.getElementById('transport-form');if(!form)return;const d=new FormData(form),p=getPlanet(state,state.active),to=state.planets.find(p=>p.id===d.get('to')),count=Number(d.get('count'));if(!to||!Number.isInteger(count)||count<1)return;const f=flightInfo(state,p,to,count);document.getElementById('transport-estimate').textContent=`${fmt(cargoCapacity(state,count))} Laderaum · ${duration(f.ms)} je Strecke · ${f.fuel} Treibstoff Flugkosten`;}
function settings(){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<form method="dialog"><button class="close plain" aria-label="Schließen">×</button></form><span class="eyebrow">SPIELSTAND & HILFE</span><h2>Dein Imperium sichern</h2><p>Lokale Sicherung nach jeder Aktion. ${cloud?.authoritative?'Der Export sichert eine lesbare Kopie. Imports und Neustarts sind für Server-Spielstände gesperrt.':'Export und Import funktionieren weiterhin.'}</p>${cloudPanel()}${pvpSettings(cloud?.pvp,galaxyBusy||cloudSaving,!!cloud?.pending)}<div class="settings-actions">${button('Spielstand exportieren','export')}${button('Spielstand importieren','import','',readOnly||cloud?.authoritative)}<input type="file" id="import-file" accept=".json,application/json" hidden>${button('Neues Spiel starten','reset','class="danger"',readOnly||cloud?.authoritative)}</div><h3>So erreichst du deine erste Kolonie</h3><ol><li>Labor 1 bauen, Sensortechnik 1 erforschen.</li><li>Werft bauen; Sonde bauen und unter Galaxie losschicken.</li><li>Labor auf Stufe 2 ausbauen; Kolonisierung erforschen.</li><li>Kolonieschiff bauen; erkundeten Planeten besiedeln.</li><li>Transporttechnik erforschen, Kolonieminen bauen und Materialien nach Hause transportieren.</li></ol><p class="fine">Bauen je Planet, Forschung imperiumsweit und Schiffbau laufen parallel. Energieknappheit reduziert Förderung. Abwesenheit wird bis zur aktuellen Gerätezeit nachberechnet. Gezeitenkraftwerke benötigen Energietechnik 3 und einen Ozeanplaneten.</p>`;document.body.append(d);d.showModal();}
app.addEventListener('submit',e=>{e.preventDefault();if(readOnly||cloudBlocked)return;if(e.target.id==='start-form'){state=newGame(new FormData(e.target).get('name'));persist(true);render();}else if(e.target.id==='transport-form'){const f=new FormData(e.target);command({type:'transport',to:f.get('to'),count:Number(f.get('count')),cargo:Object.fromEntries(RES.map(k=>[k,Number(f.get(k))]))});}});
async function command(action){if(galaxyBusy||cloudSaving){toast('Galaxie-Abgleich läuft.');return;}if(readOnly||cloudBlocked){toast(cloudBlocked?'Bitte zuerst den Cloud-Spielstand laden.':'Dieser Tab ist schreibgeschützt.');return;}try{if(cloud?.authoritative){galaxyBusy=true;adoptServer(await cloud.gameRequest({type:'command',action:{...action,planet:action.planet||state.active}}));galaxyBusy=false;}else state=act(state,action);if(['deliver','collect','station'].includes(action.type))fleetSection='overview';if(action.type==='route'||action.type==='edit-route'||action.type==='cancel-route-edit'){const form=document.getElementById('route-form');if(form){const key=fleetDraftKey(form.dataset.planet)+':route:'+form.dataset.routeId;fleetDrafts.delete(key);form.remove();}routeEditId=0;routeSection='existing';}persist(true);render();toast(action.type==='edit-route'?'Änderung vorgemerkt.':action.type==='cancel-route-edit'?'Vormerkung verworfen.':'Auftrag gestartet.');}catch(e){galaxyBusy=false;toast(e.message);if(cloud?.pending)settings();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if((cloudBlocked||galaxyBusy)&&['planet','build','research','ship','probe','colony','import','reset'].includes(a)){toast('Bitte zuerst den Cloud-Spielstand laden.');return;}if(a==='ranking-refresh'){void refreshRanking(true);}else if(a==='tab'){tab=b.dataset.tab;render();if(tab==='leaderboard')void refreshRanking();if(tab==='galaxy')void refreshGalaxy();window.scrollTo({top:0,behavior:'smooth'});}else if(a==='planet'&&!readOnly){state.active=b.dataset.id;if(b.dataset.id.startsWith('g-'))tab='overview';persist(true);render();}else if(a==='settings')settings();else if(['build','research','ship','probe','colony'].includes(a)){command({type:a,key:b.dataset.key,to:b.dataset.to,count:a==='ship'?Number(document.getElementById('build-count-'+b.dataset.key)?.value||1):1});}else if(a==='export'){try{advance(state,gameNow());const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`wahuelapa-universe-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Sicherung exportiert.');}catch(e){toast(e.message);}}else if(a==='import'&&!cloud?.authoritative)document.getElementById('import-file').click();else if(a==='reset'&&!cloud?.authoritative&&!readOnly&&confirm('Wirklich neu starten? Exportiere vorher deinen bisherigen Spielstand.')){if(cloud?.user){state=newGame(state.name);persist(true);void flushCloud();}else{state=null;try{localStorage.removeItem(SAVE_KEY);localStorage.removeItem(SAVE_KEY+'-backup');}catch{}}document.querySelector('dialog')?.close();render();}});
document.addEventListener('change',async e=>{if(e.target.id==='planet-select'&&!readOnly&&!cloudBlocked&&!galaxyBusy){state.active=e.target.value;persist(true);render();}if(e.target.id==='import-file'&&!cloud?.authoritative&&!readOnly&&!cloudBlocked&&!galaxyBusy){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Datei ist zu groß.');const incoming=parseSave(await file.text());if(!confirm('Aktuellen Spielstand durch diese Sicherung ersetzen?'))return;state=advance(incoming,Date.now());persist(true);document.querySelector('dialog')?.close();render();toast('Spielstand importiert.');}catch(err){toast(err.message);}}if(e.target.closest('#transport-form'))transportEstimate();});
document.addEventListener('input',e=>{if(e.target.closest('#transport-form'))transportEstimate();});
function tick(){if(!state||readOnly||cloudBlocked||galaxyBusy)return;try{const before=state.seq;advance(state,Date.now());persist();if(before!==state.seq){render();return;}const p=getPlanet(state,state.active);document.querySelectorAll('[data-resource]').forEach(el=>el.textContent=fmt(p.resources[el.dataset.resource]));document.querySelectorAll('[data-due]').forEach(el=>el.textContent=duration(Number(el.dataset.due)-state.time));document.querySelectorAll('[data-route-progress]').forEach(el=>{const m=state.missions.find(m=>m.id===Number(el.dataset.routeProgress));if(m){const percent=Math.round(Math.min(100,Math.max(0,100*(state.time-m.start)/m.duration)));el.setAttribute('aria-valuenow',percent);el.querySelector('i').style.width=`${percent}%`;}});document.querySelectorAll('.job').forEach(el=>{const due=Number(el.querySelector('[data-due]').dataset.due);const jobs=[p.build,p.shipjob,state.research].filter(Boolean),j=jobs.find(j=>j.end===due);if(j)el.querySelector('i').style.width=`${Math.min(100,100*(state.time-j.start)/(j.end-j.start))}%`;}); // refresh disabled affordability without replacing a user's form
 if(tab==='build'||tab==='research'){const defs=tab==='build'?BUILDINGS:TECHS;document.querySelectorAll(`[data-action="${tab==='build'?'build':'research'}"]`).forEach(b=>{const inf=tab==='build'?buildInfo(state,p,b.dataset.key):researchInfo(state,p,b.dataset.key);const busy=tab==='build'?p.build:state.research;b.disabled=!!(inf.reason||busy||!affordable(p,inf.cost));const req=b.parentElement.querySelector('.requirement');if(req&&!inf.reason&&!busy&&affordable(p,inf.cost))req.textContent='';});}
  if(tab==='fleet'){document.querySelectorAll('[data-action="ship"]').forEach(b=>{const info=shipInfo(state,p,b.dataset.key);b.disabled=!!(readOnly||info.reason||p.shipjob||!affordable(p,info.cost));});}
 }catch(e){toast(e.message);}}
try{const loaded=loadGame();state=loaded.state;if(state)advance(state,Date.now());if(loaded.recovered)toast('Letzte intakte Sicherung wiederhergestellt.');}catch(e){storageOK=false;toast(e.message);}
if(navigator.locks){navigator.locks.request('imperium-active-tab',{ifAvailable:true},async lock=>{if(!lock){readOnly=true;render();return;}void initCloud();await new Promise(()=>{});});}else{window.addEventListener('storage',e=>{if(e.key===saveKey()){readOnly=true;render();toast('Ein anderer Tab hat gespeichert. Dieser Tab bleibt schreibgeschützt.');}});}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();if(state)render();}else persist(true);});
render();setInterval(tick,1000);if(!navigator.locks)void initCloud();
setInterval(()=>{if((cloudDirty||cloud?.authoritative)&&Date.now()-cloudLastAttempt>=(cloud?.authoritative?15000:30000))void flushCloud();},5000);

function saveKey(){return cloud?.user?`${SAVE_KEY}-account-${cloud.user.id}`:SAVE_KEY;}
function cloudBadge(){if(cloudBlocked)return '⚠ Cloud laden · Einstellungen';if(!cloud?.user)return storageOK?'● Lokal gespeichert':'⚠ Speicherung fehlgeschlagen';return cloudMessage;}
function refreshCloudBadge(){const b=document.querySelector('.local-badge');if(b&&!readOnly)b.textContent=cloudBadge();}
let registrationEmail="";
function cloudPanel(){if(!CLOUD_CONFIG.enabled)return '<p class="fine">Cloud-Anmeldung wird vorbereitet. Aktuell speichert das Spiel automatisch in diesem Browser; Export sichert deinen Fortschritt zusätzlich.</p>';if(cloud?.user)return `<h3>Dein Konto</h3><p>${esc(cloud.user.email)}<br><span id="cloud-status">${esc(cloudMessage)}</span></p><div class="settings-actions">${button('Jetzt Cloud speichern','cloud-save','',cloudBlocked||cloudSaving)}${button('Cloud-Stand laden','cloud-load','',cloudSaving)}${button('Abmelden','cloud-logout','',cloudSaving)}</div><p class="fine">Automatische Cloud-Sicherung ${cloud.authoritative?'durch Serveraktionen und regelmäßigen Abgleich':'spätestens alle 30 Sekunden'}. Bei Gerätewechsel zuerst speichern. Gleichzeitige Änderungen werden nicht zusammengeführt.</p>`;return `<h3>Anmelden & auf anderen Geräten weiterspielen</h3>${registrationEmail?`<div class="notice" role="status"><strong>Bitte bestätige deine E-Mail-Adresse.</strong><p>Öffne die Bestätigungsmail für ${esc(registrationEmail)} und klicke auf den Bestätigungslink. Prüfe auch deinen Spam-Ordner. Melde dich danach hier an.</p><p>Falls für die Adresse bereits ein Konto besteht, kannst du dich mit diesem anmelden.</p></div>`:''}<form id="cloud-auth-form"><label>E-Mail<input name="email" type="email" required autocomplete="email"></label><label>Passwort<input name="password" type="password" maxlength="128" required autocomplete="current-password"></label><div class="settings-actions"><button type="submit" name="mode" value="login">Anmelden</button><button type="submit" name="mode" value="register">Konto erstellen</button></div></form><p class="fine">Beim ersten Login kannst du deinen Browser-Spielstand übernehmen. Zum Registrieren mindestens 8 Zeichen verwenden und anschließend die Bestätigungsmail öffnen.</p>`;}
function accountSetup(){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<span class="eyebrow">DEIN ERSTER CLOUD-SPIELSTAND</span><h2>Deine Heimatwelt erstellen</h2><p>Für dieses Konto gibt es noch keinen gespeicherten Spielstand.</p>${state&&!cloud?.authoritative?button(`Gast-Spielstand von ${esc(state.name)} übernehmen`,'cloud-adopt'):''}<form id="cloud-new-form"><label>Commander-Name<input name="name" maxlength="30" required value="${esc(state?.name||'')}"></label><button>Heimatwelt erstellen</button></form>${button('Abmelden','cloud-logout')}<p class="fine">Dein bisheriger Gast-Spielstand bleibt separat erhalten.</p>`;d.addEventListener('cancel',e=>e.preventDefault());document.body.append(d);d.showModal();}
async function loadAccount(discardLocal=false){if(galaxyBusy)return;cloudBlocked=true;cloudMessage='Cloud-Spielstand wird geladen …';refreshCloudBadge();try{let remote=await cloud.load();if(readOnly)return;if(!remote){accountSetup();return;}let meta=null,cached=null;try{meta=JSON.parse(localStorage.getItem(saveKey()+'-cloud-meta')||'null');cached=loadGame(localStorage,saveKey()).state;}catch{toast('Lokale Kontosicherung beschädigt. Cloud-Stand wird verwendet.');}if(!cloud.authoritative&&!discardLocal&&meta?.pending&&cached){state=advance(cached,Date.now());activeAccountId=cloud.user.id;if(meta.revision!==cloud.revision){cloudMessage='⚠ Lokaler Stand und Cloud unterscheiden sich · exportieren oder Cloud laden';toast('Nicht synchronisierte lokale Änderungen gefunden. Exportiere sie oder lade bewusst den Cloud-Stand.');settings();return;}remote=state;}state=advance(remote,gameNow());activeAccountId=cloud.user.id;cloudBlocked=false;cloudDirty=true;cloudMessage='● Cloud geladen · lokale Sicherung aktiv';try{saveGame(state,localStorage,saveKey());storageOK=true;}catch{storageOK=false;toast('Lokale Sicherung nicht möglich. Bitte exportieren.');}document.querySelector('dialog')?.remove();render();}catch(e){if(activeAccountId!==cloud?.user?.id){try{const cached=loadGame(localStorage,saveKey()).state;if(cached){state=cached;activeAccountId=cloud.user.id;}}catch{}}cloudMessage='⚠ Cloud konnte nicht geladen werden';refreshCloudBadge();toast(e.message||'Cloud nicht erreichbar.');settings();}}
async function flushCloud(){if(readOnly||!cloud?.user||cloudBlocked||cloudSaving||!state)return false;cloudSaving=true;cloudLastAttempt=Date.now();const generation=cloudGeneration;const snapshot=structuredClone(state);cloudMessage='Cloud wird gespeichert …';refreshCloudBadge();try{if(cloud.authoritative){const oldSeq=state.seq,oldPvP=JSON.stringify({...cloud.pvp,serverNow:0});adoptServer(await cloud.gameRequest({type:'sync'}));if(oldSeq!==state.seq||oldPvP!==JSON.stringify({...cloud.pvp,serverNow:0}))render();return true;}await cloud.save(snapshot);cloudDirty=cloudGeneration!==generation;cloudLastSave=Date.now();try{localStorage.setItem(saveKey()+'-cloud-meta',JSON.stringify({revision:cloud.revision,pending:cloudDirty}));}catch{}cloudMessage=`● Cloud gespeichert · ${new Date(cloudLastSave).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}`;return true;}catch(e){cloudMessage='⚠ Nur lokal gesichert · Cloud erneut versuchen';if(e instanceof CloudConflict){cloudBlocked=true;cloudMessage='⚠ Anderes Gerät gespeichert · Cloud neu laden';toast(e.message);settings();}else toast(e.message||'Cloud-Speicherung fehlgeschlagen. Lokale Sicherung bleibt erhalten.');return false;}finally{cloudSaving=false;refreshCloudBadge();if(tab==='leaderboard')void refreshRanking();const status=document.getElementById('cloud-status');if(status)status.textContent=cloudMessage;}}
async function finishAccount(initial){if(cloud?.authoritative){try{adoptServer(await cloud.createGame(initial.name));activeAccountId=cloud.user.id;cloudBlocked=false;document.querySelector('dialog')?.remove();render();}catch(e){toast(e.message);}return;}if(!cloud?.user||!cloud.loaded||cloud.revision!==0)return;state=initial;activeAccountId=cloud.user.id;cloudBlocked=false;cloudDirty=true;persist(true);const saving=flushCloud();cloudBlocked=true;if(await saving){cloudBlocked=false;document.querySelector('dialog')?.remove();render();}else settings();}
async function logoutAccount(){if(galaxyBusy){toast('Galaxie-Abgleich läuft.');return;}if(cloud?.user&&!cloudBlocked&&state){const saving=flushCloud();cloudBlocked=true;if(!await saving){cloudBlocked=!cloud.loaded;settings();return;}}cloudBlocked=true;try{await cloud.signOut();clearRanking();activeAccountId=null;state=loadGame().state;if(state)advance(state,Date.now());cloudBlocked=false;cloudDirty=false;document.querySelector('dialog')?.remove();render();}catch(e){toast(e.message);settings();}}
document.addEventListener('submit',async e=>{if(!['cloud-auth-form','cloud-new-form'].includes(e.target.id))return;e.preventDefault();if(readOnly||galaxyBusy)return;const form=e.target,d=new FormData(form);if(form.id==='cloud-new-form'){await finishAccount(newGame(d.get('name')));return;}if(cloudAuthBusy)return;cloudAuthBusy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{cloud??=await connectCloud(CLOUD_CONFIG);if(e.submitter?.value==='register'){if(String(d.get('password')).length<8)throw Error('Für ein neues Konto bitte mindestens 8 Zeichen verwenden.');await cloud.signUp(String(d.get('email')).trim(),String(d.get('password')));registrationEmail=String(d.get('email')).trim();form.reset();settings();toast('Bitte bestätige deine E-Mail-Adresse und melde dich danach an.');}else{await cloud.signIn(String(d.get('email')).trim(),String(d.get('password')));clearRanking();await loadAccount();if(tab==='leaderboard')void refreshRanking(true);}}catch(err){toast(err.message||'Anmeldung fehlgeschlagen.');}finally{cloudAuthBusy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled||readOnly)return;try{switch(b.dataset.action){case 'cloud-save':await flushCloud();break;case 'cloud-load':if(cloud?.user&&confirm('Cloud-Stand laden? Nicht synchronisierte Änderungen werden ersetzt. Bei Bedarf zuerst exportieren.'))await loadAccount(true);break;case 'cloud-logout':await logoutAccount();break;case 'cloud-adopt':if(state)await finishAccount(structuredClone(state));break;}}catch(err){toast(err.message);}});
async function initCloud(){if(!CLOUD_CONFIG.enabled||readOnly)return;cloudBlocked=true;try{cloud=await connectCloud(CLOUD_CONFIG);const user=await cloud.session();if(user)await loadAccount();else cloudBlocked=false;}catch(e){cloudMessage='⚠ Cloud-Verbindung nicht verfügbar';toast(e.message||cloudMessage); // Keep the guest save intact. Explicit login can retry.
 cloudBlocked=!!(cloud?.user&&cloud.authoritative);}render();}

document.addEventListener('submit',async e=>{if(e.target.id!=='system-name-form')return;e.preventDefault();if(!state||readOnly||cloudBlocked||galaxyBusy)return;const name=String(new FormData(e.target).get('systemName')||'').trim();if(!name||name.length>30){toast('Bitte einen Namen mit 1–30 Zeichen wählen.');return;}if(cloud?.authoritative){await serverAction({type:'rename',name});return;}state.systemName=name;persist(true);render();toast('Sonnensystem-Name gespeichert.');if(cloud?.user&&await flushCloud())void refreshGalaxy(true);});

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&galaxyExpanded&&!document.querySelector('dialog[open]')){galaxyExpanded=false;galaxyCamera=null;render();document.getElementById('galaxy-expand')?.focus();}});

document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b||b.disabled)return;
 if(b.dataset.action==='pvp-open'||b.dataset.action==='pvp-target'){if(b.dataset.to)pvpDraft.to=b.dataset.to;tab='fleet';fleetSection='pvp';render();void refreshGalaxy(true);}
 if(b.dataset.action==='pvp-toggle'){await serverAction({type:'set-pvp',enabled:!cloud.pvp.enabled});settings();}
 if(b.dataset.action==='pvp-repair')await command({type:'repair'});
 if(b.dataset.action==='pvp-retry'&&cloud?.pending)await serverAction(cloud.pending);
});
function updatePvPEstimate(form){
 const data=new FormData(form);for(const [k,v] of data)pvpDraft[k]=k==='to'?v:Number(v);
 const fleet=Object.fromEntries(Object.keys(SHIPS).filter(k=>Number(data.get(k))>0).map(k=>[k,Number(data.get(k))]));
 try{document.getElementById('pvp-estimate').textContent=pvpEstimate(state,galaxyData,data.get('to'),fleet);}catch(e){document.getElementById('pvp-estimate').textContent=e.message;}
}
document.addEventListener('input',e=>{const form=e.target.closest('#pvp-attack-form');if(form)updatePvPEstimate(form);});
document.addEventListener('change',e=>{const form=e.target.closest('#pvp-attack-form');if(form)updatePvPEstimate(form);});
document.addEventListener('submit',async e=>{
 if(e.target.id!=='pvp-attack-form')return;e.preventDefault();
 const data=new FormData(e.target),fleet=Object.fromEntries(Object.keys(SHIPS).filter(k=>Number(data.get(k))>0).map(k=>[k,Number(data.get(k))]));
 await serverAction({type:'attack',action:{from:state.active,to:data.get('to'),fleet}});
});
